// Reads every setting from the environment, checks it, and starts the page loop at the first board.
// Secrets (API keys, the Slack URL) are not copied into the run data; the HTTP nodes read them from $env.
const problems = [];
const text = v => (v === undefined || v === null ? '' : String(v)).trim();
const whole = (name, raw, fallback, min, max) => {
  const s = text(raw);
  if (s === '') return fallback;
  const n = Number(s);
  if (!Number.isInteger(n) || n < min || n > max) {
    problems.push(`${name} must be a whole number from ${min} to ${max} (it is "${s}")`);
    return fallback;
  }
  return n;
};
const columnId = v => (typeof v === 'string' && v.trim() ? v.trim() : null);
const EMAIL = /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]{2,}$/;

if (!text($env.MONDAY_API_TOKEN)) problems.push('MONDAY_API_TOKEN is empty');
const apiVersion = text($env.MONDAY_API_VERSION) || '2026-07';
if (!/^\d{4}-\d{2}$/.test(apiVersion)) problems.push(`MONDAY_API_VERSION must look like 2026-07 (it is "${apiVersion}")`);

// BOARDS_JSON: one entry per board to check
let raw = [];
try {
  raw = JSON.parse(text($env.BOARDS_JSON) || '[]');
  if (!Array.isArray(raw) || raw.length === 0) {
    problems.push('BOARDS_JSON must be a JSON list with at least one board');
    raw = [];
  }
} catch (e) {
  problems.push('BOARDS_JSON is not valid JSON: ' + e.message);
}
const seen = new Set();
const boards = raw.map((b, i) => {
  const where = `BOARDS_JSON board ${i + 1}`;
  if (!b || typeof b !== 'object' || Array.isArray(b)) {
    problems.push(`${where} is not an object`);
    return null;
  }
  const id = text(b.id);
  if (!/^\d+$/.test(id)) problems.push(`${where}: "id" must be the numeric board ID from the board URL`);
  else if (seen.has(id)) problems.push(`${where}: board ${id} is listed twice`);
  seen.add(id);
  const required = b.required_columns === undefined ? [] : b.required_columns;
  if (!Array.isArray(required) || required.some(c => !columnId(c))) problems.push(`${where}: "required_columns" must be a list of column IDs`);
  const done = b.done_labels === undefined ? [] : b.done_labels;
  if (!Array.isArray(done) || done.some(l => typeof l !== 'string')) problems.push(`${where}: "done_labels" must be a list of status labels`);
  for (const key of ['email_column', 'phone_column', 'status_column', 'owner_column']) {
    if (b[key] !== undefined && b[key] !== null && !columnId(b[key])) problems.push(`${where}: "${key}" must be a column ID or null`);
  }
  const board = {
    id,
    name: text(b.name),
    requiredColumns: Array.isArray(required) ? [...new Set(required.map(columnId).filter(Boolean))] : [],
    emailColumn: columnId(b.email_column),
    phoneColumn: columnId(b.phone_column),
    statusColumn: columnId(b.status_column),
    ownerColumn: columnId(b.owner_column),
    doneLabels: Array.isArray(done) ? done.map(l => String(l).trim().toLowerCase()).filter(Boolean) : [],
  };
  board.columnIds = [...new Set([...board.requiredColumns, board.emailColumn, board.phoneColumn, board.statusColumn, board.ownerColumn].filter(Boolean))];
  if (!board.columnIds.length) problems.push(`${where}: name at least one column to check`);
  return board;
}).filter(Boolean);

// Delivery: Slack, email, or both
const slack = text($env.SLACK_WEBHOOK_URL) !== '';
const emailTo = text($env.REPORT_EMAIL_TO).split(',').map(s => s.trim()).filter(Boolean);
if (emailTo.length) {
  if (!text($env.RESEND_API_KEY)) problems.push('REPORT_EMAIL_TO is set but RESEND_API_KEY is empty');
  if (!text($env.REPORT_EMAIL_FROM)) problems.push('REPORT_EMAIL_TO is set but REPORT_EMAIL_FROM is empty');
  if (emailTo.length > 50) problems.push('REPORT_EMAIL_TO can have at most 50 addresses');
  const bad = emailTo.filter(e => !EMAIL.test(e));
  if (bad.length) problems.push('REPORT_EMAIL_TO has invalid address(es): ' + bad.join(', '));
}
if (!slack && !emailTo.length) problems.push('Set SLACK_WEBHOOK_URL or REPORT_EMAIL_TO, otherwise nobody receives the report');

// Optional trend log on a monday.com board
const LOG_KEYS = ['key', 'date', 'board', 'score', 'items', 'issues', 'duplicates', 'missing', 'stale', 'no_owner', 'invalid'];
let log = null;
const logBoardId = text($env.HEALTH_LOG_BOARD_ID);
if (logBoardId) {
  if (!/^\d+$/.test(logBoardId)) problems.push('HEALTH_LOG_BOARD_ID must be the numeric board ID');
  let columns = {};
  try {
    columns = JSON.parse(text($env.HEALTH_LOG_COLUMNS) || '{}');
    if (!columns || typeof columns !== 'object' || Array.isArray(columns)) throw new Error('it must be a JSON object');
  } catch (e) {
    problems.push('HEALTH_LOG_COLUMNS is not valid: ' + e.message);
    columns = {};
  }
  const unknown = Object.keys(columns).filter(k => !LOG_KEYS.includes(k));
  if (unknown.length) problems.push(`HEALTH_LOG_COLUMNS has unknown key(s): ${unknown.join(', ')}. Allowed: ${LOG_KEYS.join(', ')}`);
  if (!columnId(columns.key)) problems.push('HEALTH_LOG_COLUMNS needs "key": the ID of a text column. It is how a re-run finds the row it already wrote');
  log = { boardId: logBoardId, groupId: text($env.HEALTH_LOG_GROUP_ID) || null, columns: Object.fromEntries(Object.entries(columns).filter(([k, v]) => LOG_KEYS.includes(k) && columnId(v)).map(([k, v]) => [k, v.trim()])) };
}

const timezone = text($env.REPORT_TIMEZONE) || $now.zoneName;
const local = $now.setZone(timezone);
if (!local.isValid) problems.push(`REPORT_TIMEZONE "${timezone}" is not a valid time zone, for example America/New_York`);
const countryCode = text($env.PHONE_DEFAULT_COUNTRY_CODE) || '1';
if (!/^\d{1,3}$/.test(countryCode)) problems.push('PHONE_DEFAULT_COUNTRY_CODE must be 1 to 3 digits, for example 1 or 44');

const config = {
  apiVersion,
  boards,
  staleDays: whole('STALE_DAYS', $env.STALE_DAYS, 30, 1, 3650),
  pageSize: whole('MONDAY_PAGE_SIZE', $env.MONDAY_PAGE_SIZE, 100, 1, 500),
  maxPages: whole('MONDAY_MAX_PAGES', $env.MONDAY_MAX_PAGES, 200, 1, 10000),
  maxTries: whole('MONDAY_MAX_TRIES', $env.MONDAY_MAX_TRIES, 3, 1, 10),
  maxWaitSeconds: whole('MONDAY_MAX_WAIT_SECONDS', $env.MONDAY_MAX_WAIT_SECONDS, 60, 1, 600),
  topOffenders: whole('TOP_OFFENDERS', $env.TOP_OFFENDERS, 5, 0, 25),
  countryCode,
  timezone,
  slack,
  emailTo,
  log,
};

return [{
  json: {
    ok: problems.length === 0,
    problems,
    trigger: $('Run Now').isExecuted ? 'Run Now' : 'schedule',
    startedAt: $now.toUTC().toISO(),
    snapshotDate: local.isValid ? local.toFormat('yyyy-MM-dd') : '',
    config,
    next: { boardIndex: 0, cursor: null, page: 0, attempt: 1 },
  },
}];

// Builds the GraphQL request for the next page of the current board.
// Page 1 uses boards { items_page }, which also returns the board name and checks the column IDs.
// Every later page uses next_items_page with the cursor from the page before (cursors last 60 minutes).
const cfg = $('Load Config').first().json.config;
const state = $input.first().json.next;
const board = cfg.boards[state.boardIndex];

// Email and phone come from their typed fields. Mirror, connect boards and dependency columns return no text,
// only display_value, so those are asked for too.
const ITEMS = `items {
      id name url created_at updated_at
      column_values(ids: $columnIds) {
        id type text
        ... on EmailValue { email }
        ... on PhoneValue { phone }
        ... on MirrorValue { display_value }
        ... on BoardRelationValue { display_value }
        ... on DependencyValue { display_value }
      }
    }`;
const COMPLEXITY = 'complexity { query after reset_in_x_seconds }';

let query;
let variables;
if (!state.cursor) {
  query = `query FirstPage($boardIds: [ID!], $columnIds: [String!], $limit: Int!) {
  ${COMPLEXITY}
  boards(ids: $boardIds) {
    id name url
    columns(ids: $columnIds) { id title type }
    items_page(limit: $limit) {
      cursor
      ${ITEMS.replace(/\n/g, '\n  ')}
    }
  }
}`;
  variables = { boardIds: [board.id], columnIds: board.columnIds, limit: cfg.pageSize };
} else {
  query = `query NextPage($cursor: String!, $columnIds: [String!], $limit: Int!) {
  ${COMPLEXITY}
  next_items_page(cursor: $cursor, limit: $limit) {
    cursor
    ${ITEMS}
  }
}`;
  variables = { cursor: state.cursor, columnIds: board.columnIds, limit: cfg.pageSize };
}

return [{ json: { ...state, boardId: board.id, request: { query, variables } } }];

// Reads monday.com's answer for one page, keeps the items, and picks the next step:
//   next   read the next page, or the first page of the next board
//   wait   pause, then go on (rate limit, complexity budget, a locked resource, or a 5xx answer)
//   done   every board is read
//   fatal  stop the run (bad token, daily limit, an API version or user monday.com refuses, or monday.com still
//          failing after MONDAY_MAX_TRIES)
// monday.com reports most errors with HTTP 200 and an "errors" list, so the status code alone is not enough.
// A problem with one board (deleted, no access, wrong column ID) is recorded and the other boards still run.
const cfg = $('Load Config').first().json.config;
const req = $('Build Page Request').first().json;
const res = $input.first().json;
const board = cfg.boards[req.boardIndex];
const status = Number(res.statusCode) || 0;

let body = res.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = { errors: [{ message: body.slice(0, 200) || 'empty answer' }] }; }
}
if (!body || typeof body !== 'object') body = {};
// Current API versions return { errors: [...] }; very old ones returned { error_code, error_message }
const errors = Array.isArray(body.errors) ? body.errors
  : body.error_message ? [{ message: body.error_message, extensions: { code: body.error_code } }] : [];
const codes = errors.map(e => String((e && e.extensions && e.extensions.code) || ''));
const firstError = errors.length ? `${codes[0] ? codes[0] + ': ' : ''}${errors[0].message || 'unknown error'}` : '';

const RETRY = ['COMPLEXITY_BUDGET_EXHAUSTED', 'ComplexityException', 'RATE_LIMIT_EXCEEDED', 'IP_RATE_LIMIT_EXCEEDED',
  'CONCURRENCY_LIMIT_EXCEEDED', 'maxConcurrencyExceeded', 'API_TEMPORARILY_BLOCKED', 'INTERNAL_SERVER_ERROR'];
const waitFor = seconds => Math.max(1, Math.min(cfg.maxWaitSeconds, Math.ceil(seconds)));

const base = { boardIndex: req.boardIndex, boardId: board.id, page: req.page, attempt: req.attempt, checkRun: $runIndex, records: [] };
const emit = fields => [{ json: { ...base, ...fields } }];
const afterBoard = fields => (req.boardIndex + 1 < cfg.boards.length
  ? { ...fields, route: 'next', next: { boardIndex: req.boardIndex + 1, cursor: null, page: 0, attempt: 1 } }
  : { ...fields, route: 'done' });
const boardFailed = reason => emit(afterBoard({ boardError: reason }));

// 1. Problems that would hit every board: stop the run
if (status === 401) {
  return emit({ route: 'fatal', fatalError: 'monday.com rejected the API token (HTTP 401). Check MONDAY_API_TOKEN, and the IP restrictions if your account uses them. No report was sent.' });
}
if (codes.includes('DAILY_LIMIT_EXCEEDED')) {
  return emit({ route: 'fatal', fatalError: `monday.com daily API call limit reached (${firstError}). No report was sent; it runs again on the next schedule.` });
}
if (codes.includes('InvalidVersionException')) {
  return emit({ route: 'fatal', fatalError: `monday.com does not accept API version ${cfg.apiVersion} (${firstError}). Set MONDAY_API_VERSION to a supported version, for example 2026-07. No report was sent.` });
}
if (codes.includes('USER_ACCESS_DENIED')) {
  return emit({ route: 'fatal', fatalError: `monday.com does not let the API token's user use the API (HTTP ${status}, ${firstError}). The user must be active, not a viewer, with a confirmed email. No report was sent.` });
}
// One page costs more than the 5M complexity points a single query may use. Waiting does not help; a smaller page does
if (codes.includes('REQUEST_MAX_COMPLEXITY_EXCEEDED') || codes.includes('maxComplexityExceeded')) {
  return boardFailed(`${firstError}. One page is too expensive, lower MONDAY_PAGE_SIZE (now ${cfg.pageSize})`);
}

// 2. Temporary problems: wait and try the same request again.
//    429 rate limits, 423 "resource is currently locked", 5xx, and the retryable codes above (some come with HTTP 200)
if (status === 429 || status === 423 || status >= 500 || codes.some(c => RETRY.includes(c))) {
  const reason = `HTTP ${status}${firstError ? ', ' + firstError : ''}`;
  if (req.attempt >= cfg.maxTries) {
    return emit({ route: 'fatal', fatalError: `monday.com still failing after ${req.attempt} tries (${reason}) while reading board ${board.name || board.id}. No report was sent.` });
  }
  // monday.com says how long to wait in retry_in_seconds (body) or Retry-After (header); otherwise back off 10s, 20s, 40s
  const fromBody = errors.map(e => Number(e && e.extensions && e.extensions.retry_in_seconds)).find(n => n > 0);
  const fromHeader = Number((res.headers || {})['retry-after']);
  const asked = fromBody || (fromHeader > 0 ? fromHeader : 2 ** req.attempt * 5);
  return emit({ route: 'wait', waitSeconds: waitFor(asked), askedSeconds: asked,
    waitSource: fromBody ? 'retry_in_seconds' : fromHeader > 0 ? 'Retry-After' : 'backoff', waitReason: reason,
    next: { boardIndex: req.boardIndex, cursor: req.cursor, page: req.page, attempt: req.attempt + 1 } });
}

// 3. This board cannot be read: note it and move on
if (status !== 200) return boardFailed(`HTTP ${status}${firstError ? ': ' + firstError : ''}`);
if (errors.length) return boardFailed(firstError);

const data = body.data || {};
let page;
let boardMeta = null;
if (req.page === 0) {
  const found = (data.boards || [])[0];
  if (!found) return boardFailed('board not found, archived, or the API token has no access to it');
  const columns = new Map((found.columns || []).filter(Boolean).map(c => [c.id, c]));
  const missing = board.columnIds.filter(id => !columns.has(id));
  if (missing.length) return boardFailed(`column ID(s) not on this board: ${missing.join(', ')}. Fix BOARDS_JSON`);
  // monday.com returns no text for formula columns (and their display_value is heavily rate limited), so every
  // item would look like it is missing the value. Say so instead of reporting a misleading score.
  const formula = board.columnIds.filter(id => columns.get(id).type === 'formula');
  if (formula.length) return boardFailed(`formula column(s) cannot be checked: ${formula.join(', ')}. Remove them from BOARDS_JSON`);
  boardMeta = {
    name: found.name,
    url: found.url,
    columns: Object.fromEntries([...columns].map(([id, c]) => [id, { title: c.title, type: c.type }])),
  };
  page = found.items_page;
} else {
  page = data.next_items_page;
}
if (!page || !Array.isArray(page.items)) return boardFailed('monday.com answered without an items page');

// Keep only what the checks need: email and phone from their typed fields, linked columns from display_value,
// everything else from the text
const records = page.items.map(item => {
  const v = {};
  for (const cv of item.column_values || []) {
    if (!cv || !cv.id) continue;
    const value = cv.type === 'email' ? cv.email : cv.type === 'phone' ? cv.phone
      : 'display_value' in cv ? cv.display_value : cv.text;
    v[cv.id] = value === null || value === undefined ? '' : String(value).trim();
  }
  return { id: String(item.id), name: item.name, url: item.url, createdAt: item.created_at, updatedAt: item.updated_at, v };
});
const kept = { records, boardMeta, itemsOnPage: records.length };

let step;
if (page.cursor) {
  if (page.cursor === req.cursor) return emit(afterBoard({ ...kept, boardError: 'monday.com returned the same cursor twice, so reading stopped' }));
  if (req.page + 1 >= cfg.maxPages) return emit(afterBoard({ ...kept, boardError: `stopped after ${cfg.maxPages} pages (MONDAY_MAX_PAGES); the board has more items` }));
  step = { ...kept, route: 'next', next: { boardIndex: req.boardIndex, cursor: page.cursor, page: req.page + 1, attempt: 1 } };
} else {
  step = afterBoard(kept);
}

// Not enough complexity budget left for another request like this one: wait for the reset first
const cx = data.complexity;
if (step.route === 'next' && cx && Number.isFinite(Number(cx.after)) && Number(cx.after) < Number(cx.query)) {
  const asked = (Number(cx.reset_in_x_seconds) || 60) + 1;
  step = { ...step, route: 'wait', waitSeconds: waitFor(asked), askedSeconds: asked, waitSource: 'complexity',
    waitReason: `complexity budget low (${cx.after} left, one page costs ${cx.query})` };
}
return emit(step);

// Collects every page that "Check Page" kept (one run per page) and runs the checks per board:
//   duplicates      items that share a valid email (case and spaces ignored) or a valid phone number (digits only)
//                   with an older item. The oldest item in each group is the original; the rest count.
//   missing fields  items with at least one empty required column
//   stale           not in a done status and no update for more than STALE_DAYS days (item updated_at)
//   no owner        empty owner column
//   invalid format  email or phone present but not valid
// Health score = share of items with no issues, from 0 to 100: round(100 x clean items / all items).
const start = $('Load Config').first().json;
const cfg = start.config;
const now = Date.parse(start.startedAt);
const DAY = 86400000;

// 1. Gather the pages of each board from every run of "Check Page"
const boards = cfg.boards.map(b => ({ cfg: b, meta: null, error: null, records: [], pages: 0 }));
const lastRun = $input.first().json.checkRun;
for (let run = 0; run <= lastRun; run++) {
  const page = $('Check Page').all(0, run)[0].json;
  const target = boards[page.boardIndex];
  if (page.boardMeta) target.meta = page.boardMeta;
  if (page.itemsOnPage !== undefined) {
    target.pages += 1;
    for (const r of page.records) target.records.push(r);
  }
  if (page.boardError) target.error = page.boardError;
}

// 2. Value checks
const EMAIL = /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]{2,}$/;
const phoneKey = raw => {
  const s = raw.trim();
  if (/[a-z]/i.test(s)) return null;
  let d = s.replace(/\D/g, '');
  if (s.startsWith('+')) {
    // already international
  } else if (d.startsWith('00')) {
    d = d.slice(2);
  } else if (!(d.startsWith(cfg.countryCode) && d.length >= 11)) {
    d = cfg.countryCode + d.replace(/^0/, '');
  }
  return d.length >= 8 && d.length <= 15 ? d : null;
};
const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

const results = boards.map(({ cfg: b, meta, error, records, pages }) => {
  const name = b.name || (meta && meta.name) || `Board ${b.id}`;
  const out = { id: b.id, name, url: meta ? meta.url : '', pages };
  if (error) return { ...out, status: 'failed', error, score: null, grade: 'not checked' };
  const title = id => (meta.columns[id] && meta.columns[id].title) || id;
  const checks = { duplicates: !!(b.emailColumn || b.phoneColumn), missing: b.requiredColumns.length > 0, stale: true,
    owner: !!b.ownerColumn, format: !!(b.emailColumn || b.phoneColumn) };

  const items = records.map(r => {
    const val = id => (id && r.v[id] !== undefined ? r.v[id] : '');
    const email = val(b.emailColumn);
    const phone = val(b.phoneColumn);
    const pk = phone ? phoneKey(phone) : null;
    const status = val(b.statusColumn).toLowerCase();
    const updated = Date.parse(r.updatedAt);
    const age = Number.isFinite(updated) ? Math.floor((now - updated) / DAY) : null;
    const done = !!b.statusColumn && status !== '' && b.doneLabels.includes(status);
    // Only a valid email or phone can match a duplicate, so placeholders such as "n/a" or "none" in a text
    // column never join unrelated items into one group (they count as invalid instead)
    const emailOk = email !== '' && EMAIL.test(email);
    return {
      id: r.id, name: r.name || '(no name)', url: r.url, created: Date.parse(r.createdAt) || 0, age,
      missing: b.requiredColumns.filter(id => !val(id)),
      badEmail: !!b.emailColumn && email !== '' && !emailOk,
      badPhone: !!b.phoneColumn && phone !== '' && !pk,
      stale: !done && Number.isFinite(updated) && now - updated > cfg.staleDays * DAY,
      noOwner: !!b.ownerColumn && !val(b.ownerColumn),
      keys: [emailOk ? 'e:' + email.toLowerCase() : null, pk ? 'p:' + pk : null].filter(Boolean),
      duplicateOf: null,
    };
  });

  // Duplicates: join items that share any key (A and B share a phone, B and C an email: one group of 3)
  const parent = items.map((_, i) => i);
  const find = i => { while (parent[i] !== i) { parent[i] = parent[parent[i]]; i = parent[i]; } return i; };
  const firstWithKey = new Map();
  items.forEach((it, i) => {
    for (const k of it.keys) {
      if (firstWithKey.has(k)) parent[find(i)] = find(firstWithKey.get(k));
      else firstWithKey.set(k, i);
    }
  });
  const groups = new Map();
  items.forEach((it, i) => { const root = find(i); if (!groups.has(root)) groups.set(root, []); groups.get(root).push(it); });
  let duplicateGroups = 0;
  for (const group of groups.values()) {
    if (group.length < 2) continue;
    duplicateGroups += 1;
    group.sort((x, y) => x.created - y.created || Number(x.id) - Number(y.id));
    for (const it of group.slice(1)) it.duplicateOf = group[0];
  }

  const missingByField = {};
  for (const it of items) {
    for (const id of it.missing) missingByField[title(id)] = (missingByField[title(id)] || 0) + 1;
    it.issues = [];
    if (it.duplicateOf) it.issues.push(`duplicate of ${it.duplicateOf.name}`);
    if (it.missing.length) it.issues.push('missing ' + it.missing.map(title).join(', '));
    if (it.stale) it.issues.push(`no update in ${it.age} days`);
    if (it.noOwner) it.issues.push('no owner');
    if (it.badEmail) it.issues.push('invalid email');
    if (it.badPhone) it.issues.push('invalid phone');
    it.issueCount = (it.duplicateOf ? 1 : 0) + it.missing.length + (it.stale ? 1 : 0) + (it.noOwner ? 1 : 0) + (it.badEmail ? 1 : 0) + (it.badPhone ? 1 : 0);
  }

  const total = items.length;
  const withIssues = items.filter(it => it.issueCount > 0);
  const counts = {
    items: total,
    issueItems: withIssues.length,
    duplicates: items.filter(it => it.duplicateOf).length,
    duplicateGroups,
    missingRequired: items.filter(it => it.missing.length).length,
    missingByField,
    stale: items.filter(it => it.stale).length,
    noOwner: items.filter(it => it.noOwner).length,
    invalid: items.filter(it => it.badEmail || it.badPhone).length,
    invalidEmail: items.filter(it => it.badEmail).length,
    invalidPhone: items.filter(it => it.badPhone).length,
  };
  const score = total ? Math.round((100 * (total - withIssues.length)) / total) : null;
  const grade = score === null ? 'empty' : score >= 90 ? 'Healthy' : score >= 75 ? 'Fair' : 'Needs attention';
  // Worst items: most issues first, then the longest without an update, then the oldest ID
  const offenders = withIssues
    .sort((x, y) => y.issueCount - x.issueCount || (y.age || 0) - (x.age || 0) || Number(x.id) - Number(y.id))
    .slice(0, cfg.topOffenders)
    .map(it => ({ id: it.id, name: it.name, url: it.url, issueCount: it.issueCount, issues: it.issues }));
  const summary = [
    checks.duplicates && counts.duplicates ? plural(counts.duplicates, 'duplicate', 'duplicates') : null,
    checks.missing && counts.missingRequired ? `${counts.missingRequired} missing required fields` : null,
    counts.stale ? `${counts.stale} stale` : null,
    checks.owner && counts.noOwner ? `${counts.noOwner} without an owner` : null,
    checks.format && counts.invalid ? `${counts.invalid} with an invalid email or phone` : null,
  ].filter(Boolean);
  return { ...out, status: total ? 'ok' : 'empty', checks, counts, score, grade, summary, offenders };
});

const checked = results.filter(r => r.status !== 'failed');
return [{
  json: {
    snapshotDate: start.snapshotDate,
    trigger: start.trigger,
    staleDays: cfg.staleDays,
    boards: results,
    totals: {
      boards: results.length,
      checked: checked.length,
      failed: results.length - checked.length,
      items: checked.reduce((n, r) => n + r.counts.items, 0),
      issueItems: checked.reduce((n, r) => n + r.counts.issueItems, 0),
    },
    logWanted: !!cfg.log && checked.length > 0,
    log: { status: cfg.log ? (checked.length ? 'pending' : 'skipped') : 'off', rows: [] },
    logLookup: cfg.log ? {
      query: `query FindLogRows($board: ID!, $columns: [ItemsPageByColumnValuesQuery!], $keyColumn: [String!], $limit: Int!) {
  items_page_by_column_values(board_id: $board, columns: $columns, limit: $limit) {
    cursor
    items { id name column_values(ids: $keyColumn) { id text } }
  }
}`,
      variables: {
        board: cfg.log.boardId,
        columns: [{ column_id: cfg.log.columns.key, column_values: checked.map(r => `${start.snapshotDate}|${r.id}`) }],
        keyColumn: [cfg.log.columns.key],
        limit: 500,
      },
    } : null,
  },
}];

// One row per board per day on the CRM Health Log board. The "key" column holds "<date>|<board id>".
// Rows found by the lookup are updated, the rest are created, so running the report twice on the same day
// never adds a second row. Everything goes out in one GraphQL request with one aliased mutation per board.
const a = $('Analyze Boards').first().json;
const log = $('Load Config').first().json.config.log;
const body = $input.first().json;

if (Array.isArray(body.errors) && body.errors.length) {
  const e = body.errors[0];
  return [{ json: { ready: false, log: { status: 'failed', rows: [], error: `could not look up existing rows (${(e.extensions && e.extensions.code) || 'error'}: ${e.message})` } } }];
}
const found = (body.data && body.data.items_page_by_column_values && body.data.items_page_by_column_values.items) || [];
const existing = new Map();
for (const item of found) {
  const cell = (item.column_values || []).find(c => c && c.id === log.columns.key);
  const key = cell && cell.text ? cell.text.trim().toLowerCase() : '';
  if (key && !existing.has(key)) existing.set(key, String(item.id));
}

const defs = ['$board: ID!'];
const fields = [];
const variables = { board: log.boardId };
// GraphQL rejects a declared variable that no field uses, so $group is only declared when a row is created
const useGroup = () => {
  if (!log.groupId) return '';
  if (!('group' in variables)) {
    defs.push('$group: String');
    variables.group = log.groupId;
  }
  return ', group_id: $group';
};
const rows = [];
a.boards.filter(b => b.status !== 'failed').forEach((b, i) => {
  const key = `${a.snapshotDate}|${b.id}`;
  const itemId = existing.get(key.toLowerCase());
  const values = {};
  const put = (name, value) => { if (log.columns[name]) values[log.columns[name]] = value; };
  put('key', key);
  put('date', { date: a.snapshotDate });
  put('board', b.name);
  // An empty board has no score. On an update, null clears a score written earlier the same day
  // (monday.com turns an empty string into 0 for a numbers column)
  if (b.score !== null) put('score', String(b.score));
  else if (itemId) put('score', null);
  put('items', String(b.counts.items));
  put('issues', String(b.counts.issueItems));
  if (b.checks.duplicates) put('duplicates', String(b.counts.duplicates));
  if (b.checks.missing) put('missing', String(b.counts.missingRequired));
  put('stale', String(b.counts.stale));
  if (b.checks.owner) put('no_owner', String(b.counts.noOwner));
  if (b.checks.format) put('invalid', String(b.counts.invalid));

  const alias = `row${i}`;
  variables[`values${i}`] = JSON.stringify(values);
  if (itemId) {
    defs.push(`$item${i}: ID!`, `$values${i}: JSON!`);
    fields.push(`${alias}: change_multiple_column_values(board_id: $board, item_id: $item${i}, column_values: $values${i}) { id }`);
    variables[`item${i}`] = itemId;
    rows.push({ alias, boardId: b.id, board: b.name, key, action: 'update', itemId });
  } else {
    defs.push(`$name${i}: String!`, `$values${i}: JSON!`);
    fields.push(`${alias}: create_item(board_id: $board${useGroup()}, item_name: $name${i}, column_values: $values${i}) { id }`);
    variables[`name${i}`] = `${b.name.slice(0, 240)} ${a.snapshotDate}`;  // monday.com item names are 1 to 255 characters
    rows.push({ alias, boardId: b.id, board: b.name, key, action: 'create', itemId: null });
  }
});

return [{
  json: {
    ready: rows.length > 0,
    log: { status: 'pending', rows },
    request: { query: `mutation SaveHealthLog(${defs.join(', ')}) {\n  ${fields.join('\n  ')}\n}`, variables },
  },
}];

// Matches each aliased mutation in the answer to its board. monday.com runs every mutation in the request
// and reports a failed one in "errors" with the alias in "path", so one bad row does not hide the others.
const plan = $('Plan Log Writes').first().json;
const body = $input.first().json;
const errors = Array.isArray(body.errors) ? body.errors : [];
const general = errors.filter(e => !Array.isArray(e.path) || !e.path.length);
const describe = e => `${(e.extensions && e.extensions.code) || 'error'}: ${e.message}`;

const rows = plan.log.rows.map(r => {
  const own = errors.find(e => Array.isArray(e.path) && e.path[0] === r.alias);
  const saved = body.data && body.data[r.alias] && body.data[r.alias].id;
  const problem = own || general[0];
  return { ...r, ok: !problem && !!saved, itemId: saved ? String(saved) : r.itemId,
    error: problem ? describe(problem) : saved ? null : 'monday.com returned no item ID' };
});
const failed = rows.filter(r => !r.ok);
return [{
  json: {
    log: {
      status: !failed.length ? 'saved' : failed.length === rows.length ? 'failed' : 'partial',
      created: rows.filter(r => r.ok && r.action === 'create').length,
      updated: rows.filter(r => r.ok && r.action === 'update').length,
      rows,
      error: failed.map(r => `${r.board}: ${r.error}`).join('; '),
    },
  },
}];

// Builds one Slack message and one HTML email from the analysis.
// Item and board names come from the CRM, so they are escaped for Slack (& < >) and for HTML.
// This node is reached from five places (log off, log saved, or one of three log failures); $json tells which.
const a = $('Analyze Boards').first().json;
const cfg = $('Load Config').first().json.config;

// n8n words a failed request as '500 - "<body as JSON text>"'; turn that into "HTTP 500: <message>"
const readable = e => {
  const m = /^(\d{3}) - ([\s\S]*)$/.exec((e && e.message) || '');
  if (!m) return (e && e.message) || 'request failed';
  let body = m[2];
  for (let i = 0; i < 2 && typeof body === 'string'; i++) { try { body = JSON.parse(body); } catch (x) { break; } }
  const msg = typeof body === 'string' ? body : (body && ((body.errors && body.errors[0] && body.errors[0].message) || body.message || body.error)) || '';
  return `HTTP ${m[1]}${msg ? ': ' + String(msg).slice(0, 200) : ''}`;
};
let log = $json.log || { status: 'off', rows: [] };
if ($json.error) log = { status: 'failed', rows: [], error: `monday.com did not accept the request (${readable($json.error)})` };

const esc = s => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = s => esc(s).replace(/"/g, '&quot;');
const safeUrl = u => (typeof u === 'string' && /^https?:\/\/[^\s<>|"]+$/i.test(u) ? u : '');
const slackLink = (url, label) => (safeUrl(url) ? `<${safeUrl(url)}|${esc(label)}>` : esc(label));
const htmlLink = (url, label) => (safeUrl(url) ? `<a href="${html(safeUrl(url))}" style="color:#1f5fbf">${html(label)}</a>` : html(label));
const t = a.totals;

const logNote = {
  off: '',
  skipped: 'Health log: nothing to save.',
  saved: `Health log: ${log.created || 0} new, ${log.updated || 0} updated.`,
}[log.status];
const logProblem = ['failed', 'partial'].includes(log.status)
  ? `Health log NOT ${log.status === 'partial' ? 'fully ' : ''}saved: ${log.error}. Run the report again; rows are matched by date and board, so nothing is duplicated.`
  : '';
const legend = `Score = share of items with no issues. Stale = not done and no update for more than ${a.staleDays} days.`;

// ---------- Slack ----------
const icon = b => (b.status === 'failed' ? ':warning:' : b.status === 'empty' ? ':white_circle:'
  : b.score >= 90 ? ':large_green_circle:' : b.score >= 75 ? ':large_yellow_circle:' : ':red_circle:');
const boardText = b => {
  const head = `${icon(b)} *${slackLink(b.url, b.name)}*`;
  if (b.status === 'failed') return `${head}: could not be checked. ${esc(b.error)}`;
  if (b.status === 'empty') return `${head}: empty board, nothing to check.`;
  const lines = [`${head}: score *${b.score}/100* (${b.grade})`,
    `${b.counts.items} items, ` + (b.counts.issueItems ? `${b.counts.issueItems} with issues: ${b.summary.join(', ')}.` : 'no issues found.')];
  const worst = b.offenders.map(o => `• ${slackLink(o.url, o.name)}: ${esc(o.issues.join(', '))}`);
  if (worst.length) lines.push('*Worst items*', ...worst);
  // A section holds 3,000 characters: drop worst items from the end and say how many were left out
  let cut = 0;
  while (lines.join('\n').length > 2850 && lines.length > 3) { lines.pop(); cut += 1; }
  if (cut) lines.push(`and ${cut} more`);
  return lines.join('\n');
};
let overview = `*${t.checked} of ${t.boards} boards checked*, ${t.items} items, ${t.issueItems} with at least one issue.`;
if (t.failed) overview += `\n:warning: ${t.failed} board${t.failed === 1 ? '' : 's'} could not be checked, see below.`;
if (logProblem) overview += `\n:warning: ${esc(logProblem)}`;

// Slack rejects the whole message if one section is over 3,000 characters, for example a long list of log errors
const fit = s => (s.length > 3000 ? s.slice(0, 2985) + ' (shortened)' : s);
const boardBlocks = a.boards.map(b => ({ type: 'section', text: { type: 'mrkdwn', text: fit(boardText(b)) } }));
let blocks = [
  { type: 'header', text: { type: 'plain_text', text: `CRM health report, ${a.snapshotDate}` } },
  { type: 'section', text: { type: 'mrkdwn', text: fit(overview) } },
  ...boardBlocks.flatMap(block => [{ type: 'divider' }, block]),
  { type: 'context', elements: [{ type: 'mrkdwn', text: [legend, logNote, `Run by ${a.trigger}.`].filter(Boolean).join(' ') }] },
];
const scoreText = b => (b.status === 'ok' ? `${b.score}/100` : b.status === 'empty' ? 'empty' : 'not checked');
if (blocks.length > 50) blocks = blocks.filter(block => block.type !== 'divider');  // Slack allows 50 blocks
if (blocks.length > 50) {
  // Header, overview, 46 boards, this note and the footer make 50. The boards left out are still named with their score
  const left = a.boards.slice(46);
  const note = `${left.length} more boards are not shown here, because Slack allows 50 blocks in one message: `
    + left.map(b => `${esc(b.name)} ${scoreText(b)}`).join(', ') + '.' + (cfg.emailTo.length ? ' The email report has every board.' : '');
  blocks = [...blocks.slice(0, 48), { type: 'section', text: { type: 'mrkdwn', text: fit(note) } }, blocks[blocks.length - 1]];
}
// The top level text is the notification and fallback text; Slack reads it as mrkdwn too, so it is escaped as well
const fallback = `CRM health report ${a.snapshotDate}: ` + a.boards.map(b => `${esc(b.name)} ${scoreText(b)}`).join(', ');

// ---------- Email ----------
const scored = a.boards.filter(b => b.status === 'ok').slice().sort((x, y) => x.score - y.score);
const subject = `CRM health report ${a.snapshotDate}: `
  + (scored.length ? `lowest score ${scored[0].score}/100 (${scored[0].name})` : 'no items to score')
  + (t.failed ? `, ${t.failed} board${t.failed === 1 ? '' : 's'} not checked` : '');
const cell = (b, key, check) => (b.checks[check] ? String(b.counts[key]) : 'n/a');
const td = 'style="padding:6px 8px;border-top:1px solid #d9e2ec"';
const rows = a.boards.map(b => {
  const name = `<td ${td}>${htmlLink(b.url, b.name)}</td>`;
  if (b.status === 'failed') return `<tr>${name}<td ${td} colspan="8">Could not be checked: ${html(b.error)}</td></tr>`;
  if (b.status === 'empty') return `<tr>${name}<td ${td} colspan="8">Empty board, nothing to check</td></tr>`;
  return `<tr>${name}<td ${td}><b>${b.score}</b> ${html(b.grade)}</td><td ${td}>${b.counts.items}</td><td ${td}>${b.counts.issueItems}</td>`
    + `<td ${td}>${cell(b, 'duplicates', 'duplicates')}</td><td ${td}>${cell(b, 'missingRequired', 'missing')}</td><td ${td}>${b.counts.stale}</td>`
    + `<td ${td}>${cell(b, 'noOwner', 'owner')}</td><td ${td}>${cell(b, 'invalid', 'format')}</td></tr>`;
}).join('\n');
const th = h => `<th style="padding:6px 8px;text-align:left">${h}</th>`;
const worstLists = a.boards.filter(b => b.status === 'ok' && b.offenders.length).map(b =>
  `<h3 style="margin:22px 0 6px;font-size:15px">${html(b.name)}: worst items</h3>\n<ol style="margin:0;padding-left:20px">\n`
  + b.offenders.map(o => `<li style="margin:3px 0">${htmlLink(o.url, o.name)}: ${html(o.issues.join(', '))}</li>`).join('\n') + '\n</ol>').join('\n');
const emailHtml = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#1f2933;max-width:780px">
<h2 style="margin:0 0 4px">CRM health report, ${html(a.snapshotDate)}</h2>
<p style="margin:0 0 16px;color:#52606d">${t.checked} of ${t.boards} boards checked, ${t.items} items, ${t.issueItems} with at least one issue.</p>
${logProblem ? `<p style="margin:0 0 16px;color:#b42318"><b>${html(logProblem)}</b></p>\n` : ''}<table cellspacing="0" style="border-collapse:collapse;width:100%;font-size:13px">
<tr style="background:#f0f4f8">${['Board', 'Score', 'Items', 'With issues', 'Duplicates', 'Missing fields', 'Stale', 'No owner', 'Invalid'].map(th).join('')}</tr>
${rows}
</table>
${worstLists}
<p style="margin:24px 0 0;color:#7b8794;font-size:12px">${html([legend, logNote, `Run by ${a.trigger}.`].filter(Boolean).join(' '))}</p>
</div>`;
const emailText = [`CRM health report, ${a.snapshotDate}`, `${t.checked} of ${t.boards} boards checked, ${t.items} items, ${t.issueItems} with at least one issue.`,
  ...(logProblem ? [logProblem] : []), '',
  ...a.boards.flatMap(b => {
    if (b.status === 'failed') return [`${b.name}: could not be checked. ${b.error}`, ''];
    if (b.status === 'empty') return [`${b.name}: empty board, nothing to check.`, ''];
    return [`${b.name}: score ${b.score}/100 (${b.grade}). ${b.counts.items} items, ` + (b.counts.issueItems ? `${b.counts.issueItems} with issues: ${b.summary.join(', ')}.` : 'no issues found.'),
      ...b.offenders.map(o => `  ${o.name}: ${o.issues.join(', ')} (${o.url})`), ''];
  }),
  [legend, logNote].filter(Boolean).join(' ')].join('\n');

return [{
  json: {
    snapshotDate: a.snapshotDate,
    log,
    sendSlack: cfg.slack,
    sendEmail: cfg.emailTo.length > 0,
    slack: { text: fallback, blocks },
    email: { to: cfg.emailTo, subject, html: emailHtml, text: emailText },
  },
}];

// The report is out. If anything went wrong along the way, list it so the run ends as failed
// and the error workflow sends the alert. A failed request shows up on the HTTP node's error output (output 2).
const a = $('Analyze Boards').first().json;
const report = $('Build Report').first().json;
const problems = [];
// n8n words a failed request as '500 - "<body as JSON text>"'; turn that into "HTTP 500: <message>"
const readable = e => {
  const m = /^(\d{3}) - ([\s\S]*)$/.exec((e && e.message) || '');
  if (!m) return (e && e.message) || 'request failed';
  let body = m[2];
  for (let i = 0; i < 2 && typeof body === 'string'; i++) { try { body = JSON.parse(body); } catch (x) { break; } }
  const msg = typeof body === 'string' ? body : (body && ((body.errors && body.errors[0] && body.errors[0].message) || body.message || body.error)) || '';
  return `HTTP ${m[1]}${msg ? ': ' + String(msg).slice(0, 200) : ''}`;
};

const failed = a.boards.filter(b => b.status === 'failed');
if (failed.length) problems.push(`${failed.length} board(s) could not be checked: ${failed.map(b => `${b.name} (${b.error})`).join('; ')}`);
if (['failed', 'partial'].includes(report.log.status)) problems.push(`Health log not fully saved: ${report.log.error}`);
for (const [node, label] of [['Slack: Post Report', 'Slack'], ['Email: Send Report', 'Email']]) {
  const sent = $(node);
  if (!sent.isExecuted) continue;
  const errorItems = sent.all(1);
  if (errorItems.length) problems.push(`${label} did not accept the report (${readable(errorItems[0].json.error)})`);
}

return [{ json: { ok: problems.length === 0, problems, message: `CRM health report ${a.snapshotDate} finished with problems: ${problems.join('. ')}` } }];
